window.docContents[81].resolve({"/Preface/#Type-Systems--Preface--Practicalities--Building-on-Your-Own-Copy-of-Logical-Foundations":{"contents":"This project includes a copy of the Logical Foundations files that chapters\nin this volume depend on, in their own LF/ directory, so you do not need a\nseparate Logical Foundations download to build or read this volume. If you\nhave already worked through Logical Foundations and would rather this volume\nbuild on your own work, copy the whole LF/ directory from your\nLogical Foundations download over this project's LF/ directory, then\nrebuild.\n\nExercises in this volume use the same star ratings, and the same\n\"advanced\"/\"optional\" markings, described in the Logical Foundations\nPreface.\n\n","context":"Type Systems\u0009Preface\u0009Practicalities","header":"1.3.1. Building on Your Own Copy of Logical Foundations","id":"/Preface/#Type-Systems--Preface--Practicalities--Building-on-Your-Own-Copy-of-Logical-Foundations"}});